SELECT fk.name Name,OBJECT_SCHEMA_NAME(fk.parent_object_id) ChildSchema,OBJECT_NAME(fk.parent_object_id) ChildTable,COL_NAME(fc.parent_object_id,fc.parent_column_id) ChildColumn,OBJECT_SCHEMA_NAME(fk.referenced_object_id) ParentSchema,OBJECT_NAME(fk.referenced_object_id) ParentTable,COL_NAME(fc.referenced_object_id,fc.referenced_column_id) ParentColumn,fk.is_disabled IsDisabled,fk.is_not_trusted IsNotTrusted FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=fk.object_id ORDER BY Name,fc.constraint_column_id